import json
passages={p['id']:p for p in json.load(open('/work/report-passages.json'))}
items=[]
def ids(*args):
 out=[]
 for a in args:
  if isinstance(a,tuple): out += [f'P{x:04}' for x in range(a[0],a[1]+1)]
  else: out.append(f'P{a:04}')
 return sorted(set(out))
def add(title,loc,src,status,severity,note,noise=None):
 reports=''.join(sorted({passages[p]['report'] for p in src}))
 items.append(dict(item=title,loc='quinn-proto/src/'+loc,sources=src,reports=reports,status=status,severity=severity,noise_class=noise,note=note))
add('Disabling server configuration panics on pending connections','endpoint.rs:211',ids((4,8),129,154,(179,184)),'ran','high','Scratch connection simulations panicked at endpoint.rs:211 on a duplicate Initial and :540 on accepting the pending Incoming after set_server_config(None).')
add('Rejected ordered read discards receive state','connection/streams/recv.rs:269',ids((9,13),132,162,(185,190)),'ran','high','Read abc unordered from abcdef, received IllegalOrderedRead, then received ClosedStream instead of def. The error path drops the removed receive state.')
add('ACK-delay clamp panics with valid peer minimum','connection/ack_frequency.rs:49',ids((14,18),157),'ran','high','A parameter round trip accepted minimum/maximum delays of 100 ms. candidate_max_ack_delay at RTT 10 ms panicked because clamp received inverted bounds.')
add('Optional integer transport parameters panic on decoding errors','transport_parameters.rs:472',ids((19,24),(191,196)),'ran','high','Parsing 20 00 panicked on UnexpectedEnd rather than returning Err. Both optional-integer branches unwrap decoding and do not restrict it to the declared value length.')
add('STOP then RESET returns receive credit twice','connection/streams/state.rs:356',ids((26,31),135,(216,221)),'ran','medium','With a 100-byte window and 32 unread bytes, stopping raised local_max_data to 132; the matching reset incorrectly raised it again to 164.')
add('Window restoration fails to cancel shrink debt','connection/streams/state.rs:874',ids((32,36),136,(222,227)),'ran','medium','An unused window changed from 100 to 50 to 100 produced local_max_data=150. Expansion adds credit while leaving outstanding shrink debt.')
add('Zero minimum MTU change prevents search completion','connection/mtud.rs:333',ids((37,42),139),'ran','low','The accepted minimum_change(0) setting still proposed 1451 after 32 successful component-search iterations in [1451,1452]. The stopping comparison cannot become true.')
add('Failed connection creation retains provisional CID routing state','endpoint.rs:344',ids((43,48),134,163),'ran','low','A connect using bad name returned InvalidServerName with zero connections but one known CID. new_cid inserts before fallible start_session and no rollback runs.')
add('Transport parameters reject valid wider integer encodings','transport_parameters.rs:487',ids((49,54),(234,239)),'ran','medium','Canonical 04 01 01 decoded successfully; equivalent 04 02 40 01 failed. The parser compares length against the decoded value\'s minimum encoding size.')
add('Datagram eviction excludes the incoming length','connection/datagrams.rs:39',ids((55,59),137,165,(228,233)),'ran','medium','With a four-byte send buffer, queuing aaaa then bbbb with dropping enabled delivered aaaa first. The eviction loop tests only the preexisting queued byte count.')
add('TLS-version compatibility is not checked during conversion','crypto/rustls.rs:384',ids((60,65)),'ran','medium','With rustls/tls12 enabled, a TLS-1.2-only client config converted successfully, then ordinary connect panicked at :366. Documentation promises TLS 1.3 is required for conversion to succeed.')
add('Unsupported server early-data size panics during session creation','crypto/rustls.rs:515',ids((60,61),(63,65)),'not-defect',None,'The 1024-byte configuration converted and later panicked as reported, but :425 and :465 explicitly require a QUIC server early-data size of 0 or u32::MAX. This example violates a documented configuration precondition.','other')
add('Qlog RTT metrics use seconds instead of milliseconds','connection/paths.rs:267',ids((66,71),141),'ran','low','With feature qlog, four 100 ms RTT durations became [Some(0.1);4], rather than [Some(100.0);4]. Exported recovery durations are consequently 1000 times too small.')
add('CID validation panics on short IDs','cid_generator.rs:147',ids((72,77),140,166,(197,202)),'ran','high','Validating the constructible empty ConnectionId panicked at split_at(3). The public fallible validator documents no minimum-length precondition; the same split also cannot accept lengths 1 or 2.')
add('Safe StreamId construction can violate VarInt bounds','lib.rs:257',ids((78,82),112),'ran','medium','Index 1<<60 constructed a StreamId converting to VarInt(4611686018427387906), above MAX. Encoding it also panicked at :301. The constructor accepts the unrestricted index without validation.')
add('Explicit endpoint RNG seed still calls OS entropy','endpoint.rs:77',ids((83,87)),'read','medium','Option::map_or eagerly evaluates StdRng::from_os_rng even with a seed. This contradicts EndpointConfig::rng_seed\'s entropy-free-environment contract; rand_core documents panic on entropy failure. No entropy failure was injected.')
docsrc=ids((88,92),122,144,149,168,171)
add('Default public rustdoc contains a feature-disabled verifier link','crypto/rustls.rs:279',docsrc,'not-defect',None,'Strict default rustdoc failed on the with_platform_verifier link; enabling platform-verifier resolves it. This is documentation/build cleanliness.','skill-requested-hygiene')
add('Private rustdoc contains a feature-disabled qlog link','connection/qlog.rs:45',docsrc,'not-defect',None,'Strict default rustdoc with private items failed on QlogStream. The qlog,platform-verifier documentation build passed. This is documentation/build cleanliness.','skill-requested-hygiene')
add('Datagram capability query ignores local disablement','connection/datagrams.rs:69',ids((94,98),143,167,(247,251)),'ran','low','With local datagrams disabled and peer support enabled, send returned Disabled while max_size returned Some(1414), contradicting its documented None result.')
